macro={'DXY','USDCNY','USDJPY','EURUSD','VIX'}
def get(sym,n=1800):
    f=get_index_daily_data(sym,n)
    if f is None: f=get_stock_daily_data(sym,n)
    if f is None or len(f)==0:return None
    x=f.copy(); x['date']=pd.to_datetime(x['date']); x=x.set_index('date').sort_index()
    return x['close'].astype(float)
P={s:get(s) for s in U}; P={s:x for s,x in P.items() if x is not None}
# common dates, factor: agreement of 20/60 momentum, scaled by 20d inverse vol; lag handled by using t factor -> t+1 return
px=pd.concat(P,axis=1).sort_index().ffill(); ret=px.pct_change()
r20=px.pct_change(20); r60=px.pct_change(60); vol=ret.rolling(20).std()*np.sqrt(252)
factors={
 'agreement_sharpe': (np.sign(r20)*np.sign(r60))*(0.6*r20+0.4*r60)/vol,
 'smooth_trend': (0.6*r20+0.4*r60)/vol,
 'agreement_raw': np.sign(r20)*np.sign(r60)*(0.6*r20+0.4*r60),
}
fr=ret.shift(-1)
for name,F in factors.items():
    obs=[]; turnovers=[]; ns=[]
    for d in F.index:
        a=F.loc[d]; b=fr.loc[d]; z=pd.concat([a,b],axis=1).dropna()
        if len(z)>=8:
