import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_account_dict,get_stock_daily_data,get_index_daily_data
U=get_account_dict().get('watch_list') or ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
px={}
for s in U:
 d=get_stock_daily_data(s,1200)
 if d is None or len(d)<100: d=get_index_daily_data(s,1200)
 if d is not None: px[s]=d.set_index('date').close.astype(float)
P=pd.DataFrame(px).sort_index(); R=P.pct_change(); m=R.mean(axis=1); disp=R.std(axis=1)
# A binary high-dispersion gate avoids imposing reversal in quiet regimes.
results=[]
for bw,lh,qwin,quant in [(40,3,120,.65),(60,3,120,.65),(60,5,120,.65),(60,3,180,.70),(80,5,180,.70)]:
 rows=[]
 for t in range(bw+lh+qwin,len(P)-1):
  hist=disp.iloc[max(0,t-qwin+1):t+1].dropna()
  if len(hist)<qwin*.8 or not np.isfinite(disp.iloc[t]): continue
  gate=disp.iloc[t]>=hist.quantile(quant)
  vals={}
  for s in P:
   z=pd.concat([R[s].iloc[t-bw+1:t+1],m.iloc[t-bw+1:t+1]],axis=1).dropna()
   if len(z)<20 or z.iloc[:,1].var()<=1e-12: continue
   beta=z.iloc[:,0].cov(z.iloc[:,1])/z.iloc[:,1].var(); vol=z.iloc[:,0].std()
   resid=(R[s].iloc[t-lh+1:t+1]-beta*m.iloc[t-lh+1:t+1]).sum()
   if vol>1e-8: vals[s]=(-resid/vol if gate else 0.0)
  q=pd.concat([pd.Series(vals),R.iloc[t+1].reindex(vals.keys())],axis=1).dropna()
  if len(q)>=8 and gate: rows.append(q.iloc[:,0].corr(q.iloc[:,1]))
 a=np.asarray(rows); results.append((bw,lh,qwin,quant,len(a),a.mean(),a.mean()/a.std(ddof=1),len(a)/max(1,len(P)-bw-lh-qwin)))
for x in results: print('params bw/lh/q/quant',x[:4],'gated_dates',x[4],'IC %.6f ICIR %.6f gate_date_frac %.3f'%(x[5],x[6],x[7]))
